var STOP=['a','an','the','of','in','on','at','to','for','and','or','but','is','are','was','were','be','with','from','by','as','it','this','that'];
function slugify(){
  var s=document.getElementById('in').value||'';
  var sep=document.getElementById('sep').value;
  var max=parseInt(document.getElementById('max').value,10)||0;
  // strip accents so cafe and café produce the same slug
  s=s.normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  if(document.getElementById('lower').checked)s=s.toLowerCase();
  if(!document.getElementById('nums').checked)s=s.replace(/[0-9]/g,' ');
  s=s.replace(/['’]/g,'')            // drop apostrophes rather than splitting words
     .replace(/[^a-zA-Z0-9]+/g,' ')       // everything else becomes a gap
     .trim();
  var words=s.split(/\s+/).filter(Boolean);
  if(document.getElementById('stop').checked){
    var kept=words.filter(function(w){return STOP.indexOf(w.toLowerCase())<0;});
    if(kept.length)words=kept;
  }
  var slug=words.join(sep);
  if(max>0&&slug.length>max){
    slug=slug.slice(0,max);
    var cut=slug.lastIndexOf(sep);
    if(cut>0)slug=slug.slice(0,cut);   // never end mid word
  }
  document.getElementById('out').innerHTML=slug?'<div class="out-box">'+slug+'</div>':'';
  var note=document.getElementById('note');
  note.textContent=slug?slug.length+' characters, '+words.length+' words. Example: /blog/'+slug+'/':'Type something above to build a slug.';
  window.__slug=slug;
  WT.resize();
}
['in','max'].forEach(function(id){document.getElementById(id).addEventListener('input',slugify);});
['sep','lower','stop','nums'].forEach(function(id){document.getElementById(id).addEventListener('change',slugify);});
document.getElementById('go').addEventListener('click',slugify);
document.getElementById('copy').addEventListener('click',function(){
  if(!window.__slug){document.getElementById('note').textContent='Nothing to copy yet.';return;}
  var ok=WT.copy(window.__slug);
  document.getElementById('note').textContent=ok?'Slug copied to clipboard.':'Copy failed, select the text instead.';
});
slugify();
